insert into public.places (city_id, category, name, lat, lng, is_free, emoji, short_description, full_description, sort)
select c.id, p.category, p.name, p.lat, p.lng, p.is_free, p.emoji, p.short_description, p.full_description, p.sort
from public.cities c
join (values
  ('beaches', 'Пляж Дадунхай', 18.2187, 109.5055, true, '🏖️',
   'Городской пляж, где живёт вся тусовка: пальмы, кафе у воды и море в пяти минутах от отеля. Приходи к закату — это магия!',
   'Дадунхай — это пляж, с которого я бы начала знакомство с Саньей. Тут всё рядом: кафе, душ, прокат зонтиков, и море реально в пяти минутах от большинства отелей. Днём народу много, поэтому мой лайфхак — приходи либо до 9 утра, либо за час до заката. Закат тут особенный: небо розовеет, и вся набережная гуляет с мороженым. Купайся между флажками — за буйками бывает обратное течение.',
   1),
  ('beaches', 'Пляж Ялуньвань', 18.2106, 109.6485, true, '🏖️',
   'Самый чистый пляж Саньи: белый песок и вода как в рекламе Баунти. Езжай с утра, пока все спят.',
   'Ялуньвань — это тот самый «открыточный» пляж: белый песок, прозрачная вода и никаких толп в будни до обеда. Вход на пляж свободный, хотя вдоль него стоят дорогие отели — просто иди через общественные проходы, они есть. Возьми с собой воды и перекус: цены в прибрежных кафе кусаются. Идеально ехать на такси с утра, часам к 12 начинается основной поток туристов.',
   2),
  ('beaches', 'Пляж Хайтанвань', 18.3189, 109.7389, false, '🏖️',
   'Тихий залив без толп — расскажу, где бесплатный вход на пляж и лучшие фотоспоты без единого туриста.',
   'Хайтанвань — мой фаворит для тех, кто устал от людей. Залив длинный и дикий, и тут есть легальный бесплатный вход, о котором мало кто знает (покажу точку на карте). Вода тут глубже и волны посерьёзнее, поэтому купаемся аккуратно. Зато фотки — огонь: пальмы растут почти у воды, а туристов в кадре ноль. Возьми коврик и устрой себе пикник прямо на песке.',
   3),
  ('islands', 'Остров Вузичжоу', 18.3097, 109.7606, false, '🏝️',
   '«Мальдивы Китая»: как купить билет без очереди, что взять с собой и в какой бухте вода самая бирюзовая.',
   'Вузичжоу реально оправдывает звание «Мальдив Китая» — вода бирюзовая, как на обложке. Главный секрет: билеты бери онлайн заранее, на месте очередь может съесть полдня. Паром идёт минут 20, качать может прилично — драматин в сумку не забудь. Самая красивая вода — в бухте на дальней стороне острова, туда почти никто не доходит. Еда на острове дорогая и так себе, бери снеки с собой.',
   4),
  ('islands', 'Остров Сидао', 18.2381, 109.3685, false, '🏝️',
   'Рыбацкие деревеньки вместо отелей: скутеры, кокосы и настоящая островная жизнь. Покажу маршрут на день.',
   'Сидао — это Вузичжоу наоборот: никакого глянца, зато живая рыбацкая деревня и цены как на большой земле. По острову все ездят на скутерах, аренда смешная по деньгам — настоятельно советую. Кокосы тут пьёшь прямо у домиков рыбаков за треть цены Дадунхая. Я составила маршрут на целый день: деревня, смотровая, дикий пляж и закат у причала. Паром ходит реже, чем на Вузичжоу, — расписание приложу.',
   5),
  ('sights', 'Статуя Гуаньинь в Наньшане', 18.3024, 109.1925, false, '🛕',
   '108-метровая богиня над морем: как добраться дешевле, что значат ритуалы и где смотровая без толпы.',
   'Гуаньинь в Наньшане — 108 метров богини милосердия прямо над морем, и это впечатляет даже у подножия. Ехать лучше на автобусе или карпулом: такси туда-обратно выйдет ощутимо дороже. Территория огромная, бери внутренний паровозик, если не хочешь намотать 10 км по жаре. Расскажу, что значат ритуалы у статуи, чтобы ты участвовала осознанно, а не «как все». И покажу смотровую точку сбоку, где можно сфоткать богиню без толпы в кадре.',
   6),
  ('sights', 'Тянья Хайцзяо («Край неба и угол моря»)', 18.2939, 109.3443, false, '🛕',
   'Самое романтичное место Хайнаня. Расскажу, когда ехать, чтобы не стоять в очереди к знаменитым камням.',
   'Тянья Хайцзяо — парк с теми самыми камнями «край неба, угол моря», к которым выстраивается очередь за фото. Романтики тут правда много: влюблённые приезжают сюда как к символу вечной любви. Главный лайфхак — приезжай к открытию или за полтора часа до закрытия, днём это конвейер. Помимо знаменитых камней в парке есть тихие бухты и пальмовые аллеи, где почти никого нет. Расскажу легенду камней — с ней фотка будет со смыслом.',
   7),
  ('nature', 'Парк Лухуэйтоу', 18.2254, 109.4893, true, '🌄',
   'Смотровая над городом с легендой про оленя. Поднимайся на закате — вся Санья как на ладони!',
   'Лухуэйтоу — парк на холме с лучшей смотровой площадкой города, и он бесплатный, представляешь? С названием связана милая легенда про охотника и оленя, статуя им стоит на вершине. Идеальный план: подняться за час до заката, посмотреть город при свете, а потом — как зажигаются огни Саньи. Подъём пешком минут 30, есть и электромобильчики для ленивых. Возьми воду — наверху торговых точек мало.',
   8),
  ('shopping', 'CDF Mall (duty-free)', 18.3536, 109.73, false, '🛍️',
   'Duty-free без аэропорта: как оформить покупки, что реально выгодно и где там нормальная еда.',
   'CDF Mall — огромный duty-free посреди острова: покупаешь здесь, забираешь в аэропорту при вылете. Реально выгодны косметика и парфюм — разница с нашими ценами заметная, а вот электронику считай заранее, не всегда ок. Для покупок нужен паспорт и обратный билет — без них никак, оформление займёт минут 15. Расскажу про лимиты, чтобы на таможне не было сюрпризов. И да, на верхнем этаже есть нормальный фуд-корт, не только туристические цены.',
   9),
  ('food', 'Рынок Дицы (первый рынок)', 18.2415, 109.501, true, '🦐',
   'Первый рынок города: выбираешь морепродукты внизу — наверху готовят за пару юаней. Торговаться — норма!',
   'Рынок Дицы — моё любимое приключение для живота. Схема такая: на первом этаже выбираешь живых креветок, крабов и рыбу, торгуешься (это норма, сбивай треть цены), а на втором этаже тебе всё приготовят за символические деньги. Стейлы с обработкой отличаются по вкусу — покажу проверенные, где не подменяют продукты. Иди на ранний ужин, часов в 17: выбор максимальный, а толпы ещё нет. Аллергикам и брезгливым — смотри, но сердце замирает от вкусноты!',
   10),
  ('activities', 'Сёрф-деревня Хоухай', 18.2994, 109.7223, true, '🏄',
   'Деревня сёрферов у бухты: доска и инструктор за копейки, вечером — бары прямо на песке. Мой любимый вайб!',
   'Хоухай — место с самым расслабленным вайбом во всей Санье: доски, косички, регги и бары прямо на песке. Урок сёрфинга с инструктором стоит тут смешные деньги по меркам курортов, а волны в бухте мягкие — идеально для первого раза. Днём катаешься, вечером сидишь босиком в баре с коктейлем и смотришь закат. Деревушка маленькая, всё в шаговой доступности. Если хочешь остаться — тут полно уютных гестов, но бронируй заранее в сезон.',
   11),
  ('nature', 'Парк Янода (тропический лес)', 18.563, 109.632, false, '🌿',
   'Мосты над джунглями и водопады: маршрут на день, что надеть и как выжить во влажности 90%.',
   'Янода — настоящий тропический лес с подвесными мостами над кронами и водопадами, в которых можно купаться. Это приключение на целый день, поэтому едем с утра пораньше. Надевай кроссовки (не сланцы!) и бери сменку — влажность 90% гарантирует, что ты будешь мокрая. Внутри есть два маршрута: короткий «погулять» и длинный с купанием в водопадах — бери второй, не пожалеешь. Питание внутри дорогое и простое, перекус бери с собой.',
   12),
  ('spa', 'Горячие источники Наньтянь', 18.4481, 109.6569, false, '♨️',
   '30+ бассейнов с горячей водой среди пальм. Когда ехать, какие чаны выбрать и где взять скидку.',
   'Наньтянь — это рай для замёрзших: больше тридцати бассейнов с горячей минеральной водой среди пальм. Есть чаны с кофе, вином, травами и даже с рыбками-пилингом — попробуй, это щекотно и весело. Ехать лучше ближе к вечеру: днём жарко и людно, а под вечер источники особенно кайфовые. Билеты со скидкой часто бывают на китайских площадках — покажу, где ловить. Не сиди в горячей воде дольше 15 минут подряд, чередуй с прохладными бассейнами.',
   13)
) as p(category, name, lat, lng, is_free, emoji, short_description, full_description, sort) on true
where c.slug = 'sanya';
